#include <iostream>
#include <array>

template <typename T, std::size_t N>
int binarySearch(const std::array<T, N>& items, const T& key) {
    int low = 0;
    int high = static_cast<int>(items.size()) - 1;

    while (low <= high) {
        int middle = low + (high - low) / 2;
        if (items[middle] == key) {
            return middle;
        } else if (key < items[middle]) {
            high = middle - 1;
        } else {
            low = middle + 1;
        }
    }
    return -1;
}

int main() {
    std::array<int, 15> data = {
        10, 23, 27, 48, 52, 55, 58, 60, 62, 63, 68, 72, 75, 92, 97
    };

    int key1 = 48;
    int pos1 = binarySearch(data, key1);
    if (pos1 != -1) {
        std::cout << "Key " << key1 << " found at index " << pos1 << "\n";
    } else {
        std::cout << "Key " << key1 << " not found\n";
    }

    int key2 = 22;
    int pos2 = binarySearch(data, key2);
    if (pos2 != -1) {
        std::cout << "Key " << key2 << " found at index " << pos2 << "\n";
    } else {
        std::cout << "Key " << key2 << " not found\n";
    }

    return 0;
}

#include <iostream>
#include <array>
#include <iomanip>

template <typename T, std::size_t Size>
void insertionSort(std::array<T, Size>& items) {
    for (std::size_t next = 1; next < items.size(); ++next) {
        T insert = items[next];
        std::size_t moveIndex = next;

        while (moveIndex > 0 && items[moveIndex - 1] > insert) {
            items[moveIndex] = items[moveIndex - 1];
            --moveIndex;
        }

        items[moveIndex] = insert;
    }
}

int main() {
    const std::size_t arraySize = 10;
    std::array<int, arraySize> data = {
        34, 56, 4, 10, 77, 51, 93, 30, 5, 52
    };

    std::cout << "Unsorted array:\n";
    for (std::size_t i = 0; i < arraySize; ++i) {
        std::cout << std::setw(4) << data[i];
    }

    insertionSort(data);

    std::cout << "\nSorted array:\n";
    for (std::size_t i = 0; i < arraySize; ++i) {
        std::cout << std::setw(4) << data[i];
    }
    std::cout << "\n";

    return 0;
}
